INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Demo immer live vor Ort nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Remote-Demos sind möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Feature-Präsentation?', 3, '[{"text": "Stakeholder überzeugen", "correct": true, "because": "Wert zeigen"}, {"text": "Code erklären", "correct": false, "because": "Technisch nicht primär"}, {"text": "Hardware optimieren", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer guten Demo?', 5, '[{"text": "Klarheit", "correct": true, "because": "Verständnis fördern"}, {"text": "Interaktivität", "correct": true, "because": "Einbindung stärken"}, {"text": " Lange Skripte", "correct": false, "because": "Langweilig"}, {"text": "Technische Tiefe", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Demos zeigen nur fertige Features. b) Stakeholder erwarten Perfektion.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Prototypen möglich, Perfektion nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht absolut"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Feature-Präsentation?', 4, '[{"text": "Nutzen für User", "correct": false, "because": "Kern der Demo"}, {"text": "Visuelle Darstellung", "correct": false, "because": "Wichtig für Klarheit"}, {"text": "Code-Details", "correct": true, "because": "Für Devs, nicht Stakeholder"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Demo immer technisch sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzen im Fokus"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für eine interaktive Demo?', 3, '[{"text": "Live-System", "correct": true, "because": "Echtzeit zeigt Funktionen"}, {"text": "Statische Folien", "correct": false, "because": "Wenig Interaktion"}, {"text": "Papierprotokolle", "correct": false, "because": "Zu statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Präsentation überzeugend?', 5, '[{"text": "Klarer Nutzen", "correct": true, "because": "Stakeholder interessiert"}, {"text": "Beispiele", "correct": true, "because": "Praxisnah"}, {"text": "Technische Specs", "correct": false, "because": "Nicht primär"}, {"text": "Lange Texte", "correct": false, "because": "Langweilig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Demos brauchen Vorbereitung. b) Improvisation wirkt authentisch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Improvisation riskant"}, {"text": "Beides stimmt", "correct": false, "because": "b) nicht ideal"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Stakeholder-Demo?', 4, '[{"text": "Klarheit", "correct": false, "because": "Essenziell"}, {"text": "Relevanz", "correct": false, "because": "Muss ansprechen"}, {"text": "Quellcode", "correct": true, "because": "Nicht für Stakeholder"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Demos nur für Kunden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Stakeholder"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einer erfolgreichen Demo?', 4, '[{"text": "Nutzen zeigen", "correct": true, "because": "Überzeugt Stakeholder"}, {"text": "Interaktion", "correct": true, "because": "Bindet ein"}, {"text": "Hardware-Details", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Demos nur Features zeigen sollen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzen wichtiger"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Feature-Demo?', 3, '[{"text": "Verständlichkeit", "correct": true, "because": "Klarheit überzeugt"}, {"text": "Technische Tiefe", "correct": false, "because": "Nicht für alle"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Demos brauchen Praxisbeispiele. b) Theorie reicht aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Praxis überzeugt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist schwach"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Präsentation?', 5, '[{"text": "Klarheit", "correct": true, "because": "Verständnis fördern"}, {"text": "Überzeugung", "correct": true, "because": "Stakeholder gewinnen"}, {"text": "Technische Details", "correct": false, "because": "Nicht primär"}, {"text": "Lange Dauer", "correct": false, "because": "Langweilig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Demo unwichtig?', 3, '[{"text": "Nutzen", "correct": false, "because": "Kern der Präsentation"}, {"text": "Klarheit", "correct": false, "because": "Essenziell"}, {"text": "Code-Zeilen", "correct": true, "because": "Nicht für Stakeholder"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Demos perfekt sein?', 3, '[{"text": "Nein", "correct": true, "because": "Prototypen akzeptabel"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Demo improvisiert sein darf?', 2, '[{"text": "Nein", "correct": true, "because": "Vorbereitung sicherer"}, {"text": "Ja", "correct": false, "because": "Risiko für Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für eine Demo entscheidend?', 4, '[{"text": "Anschaulichkeit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Code-Komplexität", "correct": false, "because": "Nicht relevant"}, {"text": "Statische Daten", "correct": false, "because": "Wenig überzeugend"}]');
